import { createServer } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFile, mkdir, rename, writeFile } from 'node:fs/promises';
import { extname, join, normalize } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('.', import.meta.url));
const publicDir = join(root, 'public');
const dataDir = join(root, 'data');
const dataFile = join(dataDir, 'books.json');
const port = Number(process.env.PORT || 3000);

let pendingWrite = Promise.resolve();

async function readBooks() {
  try {
    const contents = await readFile(dataFile, 'utf8');
    const books = JSON.parse(contents);
    return Array.isArray(books) ? books : [];
  } catch (error) {
    if (error.code !== 'ENOENT') throw error;
    await mkdir(dataDir, { recursive: true });
    await writeFile(dataFile, '[]\n', 'utf8');
    return [];
  }
}

function saveBooks(books) {
  pendingWrite = pendingWrite.then(async () => {
    await mkdir(dataDir, { recursive: true });
    const temporaryFile = `${dataFile}.${process.pid}.tmp`;
    await writeFile(temporaryFile, `${JSON.stringify(books, null, 2)}\n`, 'utf8');
    await rename(temporaryFile, dataFile);
  });
  return pendingWrite;
}

function sendJson(response, status, value) {
  response.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Cache-Control': 'no-store',
    'X-Content-Type-Options': 'nosniff',
  });
  response.end(JSON.stringify(value));
}

async function readBody(request) {
  let raw = '';
  for await (const chunk of request) {
    raw += chunk;
    if (raw.length > 1024 * 1024) throw new Error('Request body is too large.');
  }
  try {
    return JSON.parse(raw || '{}');
  } catch {
    throw new Error('Please send valid JSON.');
  }
}

async function serveStatic(pathname, response) {
  const relativePath = pathname === '/' ? 'index.html' : decodeURIComponent(pathname.slice(1));
  const filePath = normalize(join(publicDir, relativePath));
  if (!filePath.startsWith(`${publicDir}/`) && filePath !== join(publicDir, 'index.html')) {
    response.writeHead(403);
    response.end('Forbidden');
    return;
  }

  try {
    const file = await readFile(filePath);
    const mimeTypes = {
      '.html': 'text/html; charset=utf-8',
      '.css': 'text/css; charset=utf-8',
      '.js': 'text/javascript; charset=utf-8',
      '.svg': 'image/svg+xml',
    };
    response.writeHead(200, {
      'Content-Type': mimeTypes[extname(filePath)] || 'application/octet-stream',
      'X-Content-Type-Options': 'nosniff',
    });
    response.end(file);
  } catch (error) {
    if (error.code === 'ENOENT') {
      response.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
      response.end('Not found');
      return;
    }
    throw error;
  }
}

const server = createServer(async (request, response) => {
  const url = new URL(request.url, `http://${request.headers.host || 'localhost'}`);
  const method = request.method || 'GET';

  try {
    if (url.pathname === '/api/books' && method === 'GET') {
      sendJson(response, 200, await readBooks());
      return;
    }

    if (url.pathname === '/api/books' && method === 'POST') {
      const body = await readBody(request);
      const title = typeof body.title === 'string' ? body.title.trim() : '';
      const author = typeof body.author === 'string' ? body.author.trim() : '';
      const notes = typeof body.notes === 'string' ? body.notes.trim() : '';
      if (!title || !author) {
        sendJson(response, 400, { error: 'Add a title and author to save this book.' });
        return;
      }
      const books = await readBooks();
      const book = {
        id: randomUUID(),
        title: title.slice(0, 200),
        author: author.slice(0, 160),
        notes: notes.slice(0, 10000),
        status: 'reading',
        createdAt: new Date().toISOString(),
        finishedAt: null,
      };
      books.unshift(book);
      await saveBooks(books);
      sendJson(response, 201, book);
      return;
    }

    const bookMatch = url.pathname.match(/^\/api\/books\/([\w-]+)$/);
    if (bookMatch && method === 'GET') {
      const book = (await readBooks()).find((item) => item.id === bookMatch[1]);
      sendJson(response, book ? 200 : 404, book || { error: 'Book not found.' });
      return;
    }

    if (bookMatch && method === 'PATCH') {
      const body = await readBody(request);
      if (!['reading', 'finished'].includes(body.status)) {
        sendJson(response, 400, { error: 'Choose reading or finished as the status.' });
        return;
      }
      const books = await readBooks();
      const index = books.findIndex((item) => item.id === bookMatch[1]);
      if (index === -1) {
        sendJson(response, 404, { error: 'Book not found.' });
        return;
      }
      books[index] = {
        ...books[index],
        status: body.status,
        finishedAt: body.status === 'finished' ? (books[index].finishedAt || new Date().toISOString()) : null,
      };
      await saveBooks(books);
      sendJson(response, 200, books[index]);
      return;
    }

    if (method === 'GET' && (url.pathname === '/' || /^\/book\/[^/]+\/?$/.test(url.pathname))) {
      await serveStatic('/', response);
      return;
    }

    if (method === 'GET' && !url.pathname.startsWith('/api/')) {
      await serveStatic(url.pathname, response);
      return;
    }

    sendJson(response, 404, { error: 'Not found.' });
  } catch (error) {
    console.error(error);
    sendJson(response, 500, { error: error.message || 'Something went wrong.' });
  }
});

server.listen(port, () => {
  console.log(`Reading list is running at http://localhost:${port}`);
});
const readingList = document.querySelector('#reading-list');
const finishedList = document.querySelector('#finished-list');
const readingEmpty = document.querySelector('#reading-empty');
const finishedEmpty = document.querySelector('#finished-empty');
const dialog = document.querySelector('#add-dialog');
const form = document.querySelector('#add-form');
const toast = document.querySelector('#toast');
let toastTimer;

const escapeHtml = (value = '') => String(value).replace(/[&<>"']/g, (character) => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
}[character]));

function formatDate(value) {
  if (!value) return '';
  return new Intl.DateTimeFormat(undefined, { month: 'short', day: 'numeric', year: 'numeric' }).format(new Date(value));
}

function showToast(message) {
  toast.textContent = message;
  toast.classList.add('is-visible');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toast.classList.remove('is-visible'), 2800);
}

async function api(path, options = {}) {
  const response = await fetch(path, {
    ...options,
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
  });
  const value = await response.json();
  if (!response.ok) throw new Error(value.error || 'Something went wrong.');
  return value;
}

function renderBook(book) {
  const finished = book.status === 'finished';
  const date = finished ? book.finishedAt : book.createdAt;
  const label = finished ? 'Finished' : 'Reading now';
  return `
    <article class="book-card">
      <div class="book-card-top"><span class="book-status ${finished ? 'finished' : ''}">${label}</span></div>
      <a class="book-link" href="/book/${encodeURIComponent(book.id)}" aria-label="Open ${escapeHtml(book.title)} by ${escapeHtml(book.author)}">
        <h4 class="book-title">${escapeHtml(book.title)}</h4>
        <p class="book-author">by ${escapeHtml(book.author)}</p>
        ${book.notes ? `<p class="book-note">${escapeHtml(book.notes)}</p>` : ''}
      </a>
      <div class="card-footer"><span class="card-date">${finished ? 'Finished' : 'Added'} ${escapeHtml(formatDate(date))}</span>
        <button class="${finished ? 'reopen-button' : 'finish-button'}" type="button" data-status="${finished ? 'reading' : 'finished'}" data-id="${escapeHtml(book.id)}">${finished ? 'Move to reading' : 'Mark finished'} ${finished ? '↗' : '✓'}</button>
      </div>
    </article>`;
}

async function loadLibrary() {
  const books = await api('/api/books');
  const reading = books.filter((book) => book.status === 'reading');
  const finished = books.filter((book) => book.status === 'finished');
  readingList.innerHTML = reading.map(renderBook).join('');
  finishedList.innerHTML = finished.map(renderBook).join('');
  readingEmpty.hidden = reading.length > 0;
  finishedEmpty.hidden = finished.length > 0;
  document.querySelector('#reading-count').textContent = reading.length;
  document.querySelector('#finished-count').textContent = finished.length;
  document.querySelector('#total-count').textContent = books.length;
}

async function renderDetail(id) {
  document.querySelector('#main-content').hidden = true;
  const detail = document.querySelector('#detail-content');
  detail.hidden = false;
  detail.innerHTML = '<p class="detail-error">Opening your book…</p>';
  try {
    const book = await api(`/api/books/${encodeURIComponent(id)}`);
    const finished = book.status === 'finished';
    detail.innerHTML = `
      <a class="detail-back" href="/">← <span>Back to your shelf</span></a>
      <article class="detail-panel">
        <div class="detail-meta"><span class="book-status ${finished ? 'finished' : ''}">${finished ? 'Finished' : 'Currently reading'}</span><span class="detail-date">${finished && book.finishedAt ? `Finished ${escapeHtml(formatDate(book.finishedAt))}` : `Added ${escapeHtml(formatDate(book.createdAt))}`}</span></div>
        <h1 class="detail-title">${escapeHtml(book.title)}</h1>
        <p class="detail-author">by ${escapeHtml(book.author)}</p>
        <div class="detail-rule"></div>
        <p class="notes-label">YOUR NOTES</p>
        <p class="detail-notes ${book.notes ? '' : 'no-notes'}">${book.notes ? escapeHtml(book.notes) : 'No notes for this one yet.'}</p>
        <div class="detail-actions">
          <button class="button button-light" type="button" id="share-book">↗ &nbsp; Share this book</button>
          <button class="button ${finished ? 'button-light' : 'button-dark'}" type="button" id="detail-status" data-status="${finished ? 'reading' : 'finished'}">${finished ? 'Move to reading' : 'Mark as finished'}</button>
        </div>
      </article>`;
    document.querySelector('#share-book').addEventListener('click', async () => {
      const shareUrl = window.location.href;
      try {
        await navigator.clipboard.writeText(shareUrl);
        showToast('Link copied. Share it with someone who would love this book.');
      } catch {
        window.prompt('Copy this link to share the book:', shareUrl);
      }
    });
    document.querySelector('#detail-status').addEventListener('click', async (event) => {
      const button = event.currentTarget;
      button.disabled = true;
      try {
        await api(`/api/books/${encodeURIComponent(book.id)}`, {
          method: 'PATCH', body: JSON.stringify({ status: button.dataset.status }),
        });
        await renderDetail(book.id);
        showToast(button.dataset.status === 'finished' ? 'Added to your finished shelf.' : 'Moved back to currently reading.');
      } catch (error) {
        showToast(error.message);
        button.disabled = false;
      }
    });
  } catch (error) {
    detail.innerHTML = `<a class="detail-back" href="/">← <span>Back to your shelf</span></a><div class="detail-error"><h1>This book isn’t on your shelf.</h1><p>${escapeHtml(error.message)}</p><a href="/">Return to your reading list</a></div>`;
  }
}

function openDialog() {
  document.querySelector('#form-error').textContent = '';
  dialog.showModal();
  document.querySelector('#book-title').focus();
}

document.querySelector('#open-add').addEventListener('click', openDialog);
document.querySelectorAll('[data-add-book]').forEach((button) => button.addEventListener('click', openDialog));
document.querySelector('#close-add').addEventListener('click', () => dialog.close());
document.querySelector('#cancel-add').addEventListener('click', () => dialog.close());
dialog.addEventListener('click', (event) => {
