form.addEventListener('submit', async (event) => {
  event.preventDefault();
  const submit = document.querySelector('#save-book');
  const formError = document.querySelector('#form-error');
  const values = Object.fromEntries(new FormData(form));
  submit.disabled = true;
  formError.textContent = '';
  try {
    const book = await api('/api/books', { method: 'POST', body: JSON.stringify(values) });
    form.reset();
    dialog.close();
    await loadLibrary();
    showToast('Saved to your reading shelf.');
    if (window.location.pathname !== '/') window.location.assign(`/book/${encodeURIComponent(book.id)}`);
  } catch (error) {
    formError.textContent = error.message;
  } finally {
    submit.disabled = false;
  }
});

document.body.addEventListener('click', async (event) => {
  const button = event.target.closest('[data-status][data-id]');
  if (!button) return;
  event.preventDefault();
  button.disabled = true;
  try {
    await api(`/api/books/${encodeURIComponent(button.dataset.id)}`, {
      method: 'PATCH', body: JSON.stringify({ status: button.dataset.status }),
    });
    await loadLibrary();
    showToast(button.dataset.status === 'finished' ? 'Added to your finished shelf.' : 'Moved back to currently reading.');
  } catch (error) {
    showToast(error.message);
    button.disabled = false;
  }
});

const detailMatch = window.location.pathname.match(/^\/book\/([^/]+)\/?$/);
if (detailMatch) {
